values('dd000000-0000-4000-8000-000000000010','dd000000-0000-4000-8000-000000000001','Night market','A reusable neighborhood market with food and music.','music','Market hall','1 Market St','Floor 2','San Francisco','CA','94105','US','mapbox.fixture',37.79,-122.39,'paid',200,now()+interval '2 days',now()+interval '2 days 2 hours');
