values('dd000000-0000-4000-8000-000000000010','General','Entry',1500,'usd',100,1,'active'),('dd000000-0000-4000-8000-000000000010','Retired','Old',1000,'usd',50,2,'archived'),('dd000000-0000-4000-8000-000000000010','VIP','Upstairs',2500,'usd',50,3,'active');
