select set_config('request.jwt.claim.sub','dd000000-0000-4000-8000-000000000001',true);
set local role authenticated;
select public.duplicate_owned_event('dd000000-0000-4000-8000-000000000010','dd000000-0000-4000-8000-000000000020',public.get_owned_event_duplicate_context('dd000000-0000-4000-8000-000000000010')->>'fingerprint');
reset role;
select is((select title from events where id='dd000000-0000-4000-8000-000000000020'),'Night market — Copy','copy title');
select ok((select status='draft' and starts_at is null and ends_at is null and moderation_status='not_evaluated' and moderated_revision is null and public_history_status='never_public' and publicly_authorized_action_id is null and content_revision=1 from events where id='dd000000-0000-4000-8000-000000000020'),'fresh lifecycle and blank schedule');
