select ok(not exists(select 1 from ticket_tiers n join ticket_tiers s on n.id=s.id where n.event_id='dd000000-0000-4000-8000-000000000020' and s.event_id='dd000000-0000-4000-8000-000000000010'),'fresh tier IDs');
select is((select array_agg(sort_order order by sort_order) from ticket_tiers where event_id='dd000000-0000-4000-8000-000000000020'),array[1,3]::smallint[],'preserve sort slots');
select ok((select bool_and(status='draft' and version=1) from ticket_tiers where event_id='dd000000-0000-4000-8000-000000000020'),'fresh draft tier state');
select is((select minimum_age from private.event_risk_disclosures where event_id='dd000000-0000-4000-8000-000000000020'),'21_plus','factual requirements copied');
select is((select count(*) from private.event_policy_acceptances where event_id='dd000000-0000-4000-8000-000000000020'),0::bigint,'no acceptance copied');
select is((select count(*) from orders where event_id='dd000000-0000-4000-8000-000000000020'),0::bigint,'zero orders');
select is((select count(*) from tickets where event_id='dd000000-0000-4000-8000-000000000020'),0::bigint,'zero tickets');
select results_eq($$select organizer_id,description,category,venue_name,address_line1,address_line2,city,region,postal_code,country_code,mapbox_feature_id,latitude,longitude,timezone,admission_type,capacity from events where id='dd000000-0000-4000-8000-000000000020'$$,$$select organizer_id,description,category,venue_name,address_line1,address_line2,city,region,postal_code,country_code,mapbox_feature_id,latitude,longitude,timezone,admission_type,capacity from events where id='dd000000-0000-4000-8000-000000000010'$$,'entire reusable event allowlist matches');
select is(private.event_duplicate_configuration('dd000000-0000-4000-8000-000000000020')->'requirements',private.event_duplicate_configuration('dd000000-0000-4000-8000-000000000010')->'requirements','all seven factual disclosures match');
create function pg_temp.reject_duplicate_disclosure() returns trigger language plpgsql as $$begin if new.event_id='dd000000-0000-4000-8000-000000000030' then raise exception 'INJECTED_COPY_FAILURE'; end if; return new; end;$$;
create trigger duplicate_proof_reject before insert on private.event_risk_disclosures for each row execute function pg_temp.reject_duplicate_disclosure();
set local role authenticated;
select throws_ok($$select public.duplicate_owned_event('dd000000-0000-4000-8000-000000000010','dd000000-0000-4000-8000-000000000030',public.get_owned_event_duplicate_context('dd000000-0000-4000-8000-000000000010')->>'fingerprint')$$,'P0001','INJECTED_COPY_FAILURE','injected late transaction failure');
reset role;
select is((select count(*) from events where id='dd000000-0000-4000-8000-000000000030'),0::bigint,'late failure rolls back event');
select is((select count(*) from ticket_tiers where event_id='dd000000-0000-4000-8000-000000000030'),0::bigint,'late failure rolls back copied tiers');
select is((select count(*) from private.event_change_state where event_id='dd000000-0000-4000-8000-000000000030'),0::bigint,'late failure rolls back bookkeeping');
drop trigger duplicate_proof_reject on private.event_risk_disclosures;
select set_config('request.jwt.claim.sub','dd000000-0000-4000-8000-000000000002',true);
set local role authenticated;
select throws_ok($$select public.get_owned_event_duplicate_context('dd000000-0000-4000-8000-000000000010')$$,'P0001','EVENT_NOT_FOUND','foreign context denied');
select throws_ok($$select public.duplicate_owned_event('dd000000-0000-4000-8000-000000000010',gen_random_uuid(),'bad')$$,'P0001','EVENT_NOT_FOUND','foreign finalization denied');
reset role;
select ok(not has_function_privilege('anon','public.duplicate_owned_event(uuid,uuid,text,text)','execute'),'anonymous cannot execute');
select set_config('request.jwt.claim.sub','dd000000-0000-4000-8000-000000000001',true);
update events set moderation_status='blocked' where id='dd000000-0000-4000-8000-000000000010';
set local role authenticated;
select throws_ok($$select public.get_owned_event_duplicate_context('dd000000-0000-4000-8000-000000000010')$$,'P0001','DUPLICATE_MODERATION_BLOCKED','blocked context denied');
select throws_ok($$select public.duplicate_owned_event('dd000000-0000-4000-8000-000000000010',gen_random_uuid(),'bad')$$,'P0001','DUPLICATE_MODERATION_BLOCKED','blocked finalization denied');
reset role;
update events set moderation_status='removed' where id='dd000000-0000-4000-8000-000000000010';
set local role authenticated;
select throws_ok($$select public.get_owned_event_duplicate_context('dd000000-0000-4000-8000-000000000010')$$,'P0001','DUPLICATE_MODERATION_BLOCKED','removed denied');
reset role;
select * from finish();
rollback;
